//! C-alignment regression tests (step H7: the FTS5 read side as a port of ext/fts5 — index reader with forward and
//! reverse segment iteration and doclist indexes, expression evaluation, the cursor plans of `fts5FilterMethod`, the
//! sorter statement of `ORDER BY rank`, the extension API and the auxiliary functions — and virtual-table scans the
//! engine steps row by row like `OP_VFilter` / `OP_VColumn` / `OP_VNext`). GENERATED by
//! target/perf-work/h7/gen_tests7.py: every expected value is what C SQLite 3.54.1 returns (rows in order, error
//! messages). The cases marked "fails before H7" in the generator output differ from C with the code before this
//! step; the others guard paths this step rewrote. Nothing here depends on files outside the repository.
use crate::Connection;

struct TempDb(std::path::PathBuf);

impl TempDb {
    fn new(name: &str) -> Self {
        let path =
            std::env::temp_dir().join(format!("sqliters-h7-{}-{name}.db", std::process::id()));
        let db = Self(path);
        db.remove_all();
        db
    }
    fn remove_all(&self) {
        for suffix in ["", "-journal", "-wal", "-shm"] {
            let mut s = self.0.clone().into_os_string();
            s.push(suffix);
            let _ = std::fs::remove_file(std::path::PathBuf::from(s));
        }
    }
}

impl Drop for TempDb {
    fn drop(&mut self) {
        self.remove_all();
    }
}

/// Runs the statements like `sqlite3_exec` (prepare, step until done or error: the rows a statement returns before
/// it fails count); `c_out` is what the C shell prints for them (rows as `a|b`, one per line), `c_errors` the messages
/// of the statements that fail, in order.
fn assert_rows_and_errors_are_what_c_returns(
    name: &str,
    stmts: &[&str],
    c_out: &str,
    c_errors: &[&str],
) {
    let db = TempDb::new(name);
    let conn = Connection::open(&db.0).unwrap();
    let mut out = String::new();
    let mut errors: Vec<String> = Vec::new();
    for sql in stmts {
        let mut stmt = match conn.prepare(sql) {
            Ok(s) => s,
            Err(e) => {
                errors.push(e.message.clone());
                continue;
            }
        };
        loop {
            match stmt.step() {
                Ok(crate::StepResult::Row(row)) => {
                    let cells: Vec<String> = row
                        .values()
                        .iter()
                        .map(|v| match v {
                            sqliters_types::Value::Null => String::new(),
                            sqliters_types::Value::Integer(i) => i.to_string(),
                            sqliters_types::Value::Real(r) => format!("{r:?}"),
                            sqliters_types::Value::Text(s) => s.to_string(),
                            sqliters_types::Value::Blob(b) => {
                                String::from_utf8_lossy(&b[..]).into_owned()
                            }
                        })
                        .collect();
                    out.push_str(&cells.join("|"));
                    out.push('\n');
                }
                Ok(crate::StepResult::Done) => break,
                Err(e) => {
                    errors.push(e.message.clone());
                    break;
                }
            }
        }
        drop(stmt);
    }
    assert!(conn.try_close().is_ok());
    assert_eq!(out, c_out, "{name}: rows");
    assert_eq!(errors, c_errors, "{name}: error messages");
}

/// a MATCH scan is stepped row by row: an auxiliary function that fails on a later row (its %_docsize row is gone) is not reached when LIMIT stops the scan; without LIMIT the statement fails.
#[test]
fn fts5_scan_stops_at_limit_before_a_failing_row() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_scan_stops_at_limit_before_a_failing_row",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta');",
            "INSERT INTO ft VALUES('hello there world', 'beta gamma');",
            "INSERT INTO ft VALUES('goodbye world', 'gamma delta hello');",
            "INSERT INTO ft VALUES('one two three', 'x y z');",
            "INSERT INTO ft VALUES('hello hello hello', 'x hello z');",
            "DELETE FROM ft_docsize WHERE id = 3;",
            "SELECT rowid, printf('%.6f', bm25(ft)) FROM ft WHERE ft MATCH 'hello' LIMIT 2;",
            "SELECT rowid, snippet(ft, 0, '[', ']', '..', 3) FROM ft WHERE ft MATCH 'hello' LIMIT 2;",
            "SELECT rowid, upper(highlight(ft, 0, '[', ']')) FROM ft WHERE ft MATCH 'hello' ORDER BY rowid DESC LIMIT 1;",
            "SELECT rowid, printf('%.6f', bm25(ft)) FROM ft WHERE ft MATCH 'hello';",
            "SELECT rowid FROM ft WHERE ft MATCH 'hello' AND bm25(ft) < 0.0 LIMIT 2;",
        ],
        "1|-0.000001\n2|-0.000001\n1|[hello] world one..\n2|[hello] there world\n5|[HELLO] [HELLO] [HELLO]\n1|-0.000001\n2|-0.000001\n1\n2\n",
        &[
            "database disk image is malformed",
        ],
    );
}

/// OFFSET is applied before the result columns of a row are computed (`codeOffset`): the function that would fail on a skipped row is not called; `LIMIT 0` does not even open the cursor (no error for a bad MATCH expression).
#[test]
fn fts5_offset_rows_are_skipped_before_result_columns() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_offset_rows_are_skipped_before_result_columns",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta');",
            "INSERT INTO ft VALUES('hello there world', 'beta gamma');",
            "INSERT INTO ft VALUES('goodbye world', 'gamma delta hello');",
            "INSERT INTO ft VALUES('one two three', 'x y z');",
            "INSERT INTO ft VALUES('hello hello hello', 'x hello z');",
            "SELECT rowid, snippet(ft, 9, '', '', '', 1) FROM ft WHERE ft MATCH 'three' LIMIT 1 OFFSET 1;",
            "SELECT rowid, snippet(ft, 9, '', '', '', 1) FROM ft WHERE ft MATCH 'three';",
            "SELECT rowid FROM ft WHERE ft MATCH 'AND' LIMIT 0;",
            "SELECT rowid FROM ft WHERE ft MATCH 'AND' LIMIT 1;",
            "SELECT rowid, a FROM ft WHERE ft MATCH 'hello' LIMIT 2 OFFSET 1;",
        ],
        "2|hello there world\n3|goodbye world\n",
        &[
            "column index out of range",
            "fts5: syntax error near \"AND\"",
        ],
    );
}

