/// the table-name column is the cursor id (`++pGlobal->iNextId` per xOpen, also for the cursors of xQueryPhrase and of the sorter statement); `'*id'` and `'*reads'` report the id and the number of %_data blocks read (`p->nRead`).
#[test]
fn fts5_cursor_ids_and_special_queries() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_cursor_ids_and_special_queries",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta');",
            "INSERT INTO ft VALUES('hello there world', 'beta gamma');",
            "INSERT INTO ft VALUES('goodbye world', 'gamma delta hello');",
            "INSERT INTO ft VALUES('one two three', 'x y z');",
            "INSERT INTO ft VALUES('hello hello hello', 'x hello z');",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT rowid, ft FROM ft WHERE ft MATCH 'hello' LIMIT 2;",
            "SELECT rowid, ft, bm25(ft) < 0 FROM ft WHERE ft MATCH 'world' ORDER BY rank LIMIT 2;",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT ft FROM ft WHERE ft MATCH '*reads';",
            "SELECT ft FROM ft WHERE ft MATCH '*zap';",
            "SELECT bm25(a) FROM ft WHERE ft MATCH 'hello';",
            "SELECT bm25(1) FROM ft WHERE ft MATCH 'hello';",
        ],
        "1\n1|2\n2|2\n2|3|1\n3|3|1\n7\n35\n",
        &[
            "unknown special query: zap",
            "no such cursor: 0",
            "unable to use function bm25 in the requested context",
        ],
    );
}

