/// a row the index has but the content table has not: `fts5SeekCursor` fails when a column is read (xColumn names the content table, an auxiliary function reports SQLITE_CORRUPT_VTAB); rowids and counts do not read the content; the scan stops at LIMIT before it gets there.
#[test]
fn fts5_missing_content_row_is_reported_when_the_column_is_read() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_missing_content_row_is_reported_when_the_column_is_read",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta');",
            "INSERT INTO ft VALUES('hello there world', 'beta gamma');",
            "INSERT INTO ft VALUES('goodbye world', 'gamma delta hello');",
            "INSERT INTO ft VALUES('one two three', 'x y z');",
            "INSERT INTO ft VALUES('hello hello hello', 'x hello z');",
            "DELETE FROM ft_content WHERE id = 3;",
            "SELECT rowid FROM ft WHERE ft MATCH 'hello';",
            "SELECT count(*) FROM ft WHERE ft MATCH 'hello';",
            "SELECT rowid, a FROM ft WHERE ft MATCH 'hello' LIMIT 2;",
            "SELECT rowid, a FROM ft WHERE ft MATCH 'hello';",
            "SELECT rowid, highlight(ft, 0, '[', ']') FROM ft WHERE ft MATCH 'hello';",
            "SELECT rowid, printf('%.6f', bm25(ft)) FROM ft WHERE ft MATCH 'hello';",
            "SELECT rowid, a FROM ft WHERE ft MATCH 'hello' ORDER BY rank;",
        ],
        "1\n2\n3\n5\n4\n1|hello world one two\n2|hello there world\n1|hello world one two\n2|hello there world\n1|[hello] world one two\n2|[hello] there world\n1|-0.000001\n2|-0.000001\n3|-0.000001\n5|-0.000002\n5|hello hello hello\n2|hello there world\n",
        &[
            "fts5: missing row 3 from content table 'main'.'ft_content'",
            "database disk image is malformed",
            "fts5: missing row 3 from content table 'main'.'ft_content'",
        ],
    );
}

