/// aggregates without GROUP BY: the ORDER BY is dropped (its columns are read on the first row only: `rank` runs the rank function once, which shows in the cursor ids through xQueryPhrase), a lone max(X) / min(rowid) asks for the order of X and leaves the loop after the first row (`*reads`), LIMIT 0 does not open the cursor, an ORDER BY expression without columns is never computed.
#[test]
fn fts5_aggregate_scans_follow_the_c_program() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_aggregate_scans_follow_the_c_program",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b);",
            "INSERT INTO ft VALUES('hello world one two', 'alpha beta');",
            "INSERT INTO ft VALUES('hello there world', 'beta gamma');",
            "INSERT INTO ft VALUES('goodbye world', 'gamma delta hello');",
            "INSERT INTO ft VALUES('one two three', 'x y z');",
            "INSERT INTO ft VALUES('hello hello hello', 'x hello z');",
            "DELETE FROM ft_docsize WHERE id = 3;",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT count(*) FROM ft WHERE ft MATCH 'hello' ORDER BY rank LIMIT 3;",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT count(*), max(rowid) FROM ft WHERE ft MATCH 'hello' ORDER BY bm25(ft);",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT max(rowid) FROM ft WHERE ft MATCH 'gamma' ORDER BY rank;",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT max(rowid) FROM ft WHERE ft MATCH 'hello';",
            "SELECT ft FROM ft WHERE ft MATCH '*reads';",
            "SELECT min(rowid) FROM ft WHERE ft MATCH 'world';",
            "SELECT ft FROM ft WHERE ft MATCH '*reads';",
            "SELECT max(rank) FROM ft WHERE ft MATCH 'world';",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT min(rank) < 0 FROM ft WHERE ft MATCH 'one';",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT count(*) FROM ft WHERE ft MATCH 'hello' LIMIT 0;",
            "SELECT max(rowid) FROM ft WHERE ft MATCH 'world' LIMIT 1 OFFSET 1;",
            "SELECT ft FROM ft WHERE ft MATCH '*id';",
            "SELECT ft FROM ft WHERE ft MATCH '*reads';",
            "CREATE TABLE t(a, b);",
            "INSERT INTO t VALUES(1, 'x'), (2, 'y'), (3, 'x');",
            "SELECT count(*) FROM t ORDER BY abs(-9223372036854775807 - 1);",
            "SELECT count(*) FROM t HAVING count(*) > 1 ORDER BY abs(-9223372036854775807 - 1);",
            "SELECT count(*) FROM t GROUP BY b ORDER BY abs(-9223372036854775807 - 1);",
            "SELECT b, count(*) FROM t GROUP BY b ORDER BY 2 DESC, 1;",
        ],
        "1\n4\n4\n4|5\n6\n9\n5\n45\n1\n50\n17\n1\n20\n22\n79\n3\n3\nx|2\ny|1\n",
        &[
            "database disk image is malformed",
            "database disk image is malformed",
            "integer overflow",
        ],
    );
}

/// expression evaluation: column filters with braces and negation, `^` first-token anchors, NEAR with distances, phrases with `+`, NOT / OR nests, implicit AND, column MATCH, rowid IN lists, tokendata=1 tables (`fts5SetupTokendataIter`), LIKE / GLOB on a trigram table (`sqlite3Fts5ExprPattern`).
#[test]
fn fts5_tokendata_and_expression_forms() {
    assert_rows_and_errors_are_what_c_returns(
        "fts5_tokendata_and_expression_forms",
        &[
            "CREATE VIRTUAL TABLE ft USING fts5(a, b, c);",
            "CREATE VIRTUAL TABLE td USING fts5(a, tokendata=1);",
            "CREATE VIRTUAL TABLE tg USING fts5(a, tokenize='trigram', detail=none);",
            "INSERT INTO ft VALUES('one two three', 'four five six', 'one six');",
            "INSERT INTO ft VALUES('two one', 'six one four', 'three');",
            "INSERT INTO ft VALUES('seven', 'one two', 'two one five');",
            "INSERT INTO ft VALUES('three two one zero', 'x', 'y one');",
            "INSERT INTO td VALUES('one two three'), ('two one'), ('three three');",
            "INSERT INTO tg VALUES('abcdefgh'), ('xyzabcxyz'), ('hello world'), ('ABCDEF');",
            "SELECT rowid FROM ft WHERE ft MATCH '{a b} : one';",
            "SELECT rowid FROM ft WHERE ft MATCH '-a : one';",
            "SELECT rowid FROM ft WHERE ft MATCH 'c : (one OR five) NOT a : two';",
            "SELECT rowid FROM ft WHERE ft MATCH '^one';",
            "SELECT rowid FROM ft WHERE ft MATCH '^one + two';",
            "SELECT rowid FROM ft WHERE ft MATCH 'a : ^two';",
            "SELECT rowid FROM ft WHERE ft MATCH 'NEAR(one three, 1)';",
            "SELECT rowid FROM ft WHERE ft MATCH 'NEAR(one three, 0)';",
            "SELECT rowid FROM ft WHERE ft MATCH 'NEAR(one two three)';",
            "SELECT rowid FROM ft WHERE ft MATCH 'one + two';",
            "SELECT rowid FROM ft WHERE ft MATCH '\"two one\" OR \"five six\"';",
            "SELECT rowid FROM ft WHERE ft MATCH '(one two) NOT (four OR seven)';",
            "SELECT rowid FROM ft WHERE b MATCH 'one';",
            "SELECT rowid FROM ft WHERE ft MATCH 'one' AND rowid IN (1, 3, 9);",
            "SELECT rowid FROM ft WHERE ft MATCH 'one' AND a MATCH 'two' AND rowid > 1;",
            "SELECT rowid FROM ft WHERE ft MATCH 'on* NOT thr*' ORDER BY rowid DESC;",
            "SELECT rowid FROM ft WHERE ft MATCH '\"\" OR six';",
            "SELECT rowid FROM ft WHERE ft MATCH 'nosuch : one';",
            "SELECT rowid FROM ft WHERE ft MATCH 'one AND';",
            "SELECT rowid FROM ft WHERE ft MATCH 'NEAR(one two, x)';",
            "SELECT rowid FROM ft WHERE ft MATCH 'NOTNEAR(one two)';",
            "SELECT rowid, highlight(td, 0, '[', ']') FROM td WHERE td MATCH 'three';",
            "SELECT rowid FROM td WHERE td MATCH 'one two';",
            "SELECT rowid FROM td WHERE td MATCH 't*' ORDER BY rowid DESC;",
            "SELECT rowid FROM tg WHERE a LIKE '%abc%';",
            "SELECT rowid FROM tg WHERE a GLOB '*abc*';",
            "SELECT rowid FROM tg WHERE a LIKE '%lo wo%';",
            "SELECT rowid FROM tg WHERE tg MATCH 'cde';",
        ],
        "1\n2\n3\n4\n1\n2\n3\n4\n3\n1\n3\n1\n3\n2\n1\n4\n1\n4\n1\n3\n1\n2\n3\n4\n4\n2\n3\n1\n3\n2\n4\n3\n1\n2\n1|one two [three]\n3|[three] [three]\n1\n2\n3\n2\n1\n1\n2\n4\n1\n2\n3\n1\n4\n",
        &[
            "no such column: nosuch",
            "fts5: syntax error near \"\"",
            "expected integer, got \"x\"",
            "fts5: syntax error near \"NOTNEAR\"",
        ],
    );
}
